// RulesLayout is the layout the repositories run the behaviors' core over,
// and a hand-written caller of rules.Execute may: rules.Host{Layout:
// RulesLayout, Store: rulespostgres.NewStore(tx)}.
var RulesLayout = rules.MustParseLayout([]byte(rulesLayoutJSON))

// behaviorCallerKey is the context key WithBehaviorCaller stores a caller under.
const behaviorCallerKey contextKey = "orm_behavior_caller"

// WithBehaviorCaller returns ctx whose behaviors' commands run as caller
// (D103): the subject and the permissions a behavior's config names, such
// as a transition's. Unset, a command runs as the context's user holding
// no permissions.
func WithBehaviorCaller(ctx context.Context, caller rules.Caller) context.Context {
	return context.WithValue(ctx, behaviorCallerKey, caller)
}

// behaviorCaller is the caller a behavior's command runs as: the one
// WithBehaviorCaller names, else the context's user holding no
// permissions, else a subject of "".
func behaviorCaller(ctx context.Context) rules.Caller {
	if caller, ok := ctx.Value(behaviorCallerKey).(rules.Caller); ok {
		return caller
	}
	if HasUserID(ctx) {
		return rules.Caller{Subject: fmt.Sprint(GetUserID(ctx))}
	}
	return rules.Caller{}
}

// behaviorPreconditionsKey is the context key WithPreconditions stores
// preconditions under.
const behaviorPreconditionsKey contextKey = "orm_behavior_preconditions"

// WithPreconditions returns ctx whose behaviors' commands present
// preconditions (D16, D104): what the caller asserts of the row, each use's
// entry by its use id
// (rules.Preconditions{"Lease": JobLeasePrecondition{...}}),
// which the use's guard holds the command to. Every command a repository
// runs through the core with ctx presents them: the core checks them
// against each use's behavior before it reads the row of an update, a
// delete or an operation, and refuses as PreconditionsError an entry for a
// use the table lacks or whose behavior takes none, and any other command
// that presents one, a create, an upsert's insert and a deadline among
// them. A table that composes no behavior reads none.
func WithPreconditions(ctx context.Context, preconditions rules.Preconditions) context.Context {
	return context.WithValue(ctx, behaviorPreconditionsKey, preconditions)
}

// behaviorPreconditions are the preconditions WithPreconditions names; nil
// for none.
func behaviorPreconditions(ctx context.Context) rules.Preconditions {
	preconditions, _ := ctx.Value(behaviorPreconditionsKey).(rules.Preconditions)
	return preconditions
}

// rulesHost is the host the core runs on in tx.
func rulesHost(tx pgx.Tx) rules.Host {
	return rules.Host{Layout: RulesLayout, Store: rulespostgres.NewStore(tx)}
}

// behaviorNotFound is err as a repository returns it: the core's not_found
// of the row wraps ErrNotFound as well as the refusal, as the repository's
// own statements return ErrNotFound.
func behaviorNotFound(err error, typeName string, id any) error {
	if rules.IsNotFound(err) {
		return fmt.Errorf("%w: %s %v: %w", ErrNotFound, typeName, id, err)
	}
	return err
}
